[[nodiscard]] static inline std::string toString(Flags::Volume val) {
  switch(val) {
  case Flags::Volume::NONE:
    return "NONE";
  case Flags::Volume::CTRL:
    return "CTRL";
  case Flags::Volume::IND:
    return "IND";
  case Flags::Volume::MONITOR:
    return "MONITOR";
  default:
    return std::to_string(static_cast<int8_t>(val));
  }
}
